INSERT INTO publicaciones (id, descripcion, fecha, mascota_id, id_miembro, ubicacion_id, activo) VALUES
(1, 'Encontre un perro en la zona norte, le puse Rocky de carinio. Parece amigable. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 88 DAY), 1, 3, 1, 1),
(2, 'Encontre un gato en barrio Parque, le puse Michi de carinio. No tenia collar ni chapita. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 86 DAY), 2, 4, 2, 1),
(3, 'Encontre un perro en cerca de la terminal, le puse Max de carinio. Esta un poco asustado pero come bien. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 84 DAY), 3, 5, 3, 1),
(4, 'Se perdio mi gato llamado Simba en la costa. Es responde a su nombre. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 82 DAY), 4, 6, 4, 1),
(5, 'Se perdio mi perro llamado Toby en barrio Belgrano. Es es de contextura pequenia. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 80 DAY), 5, 7, 5, 1),
(6, 'Luna, el gato que estaba en adopcion en zona sur, ya encontro su familia definitiva. Gracias a todos los que compartieron la publicacion.', DATE_SUB(CURDATE(), INTERVAL 78 DAY), 6, 8, 6, 1),
(7, 'Encontre un perro en las quintas, le puse Firulais de carinio. Esta en buen estado de salud. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 76 DAY), 7, 9, 7, 1),
(8, 'Se perdio mi gato llamado Salem en cerca de la plaza principal. Es muy carinioso. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 74 DAY), 8, 10, 8, 1),
(9, 'Encontre un perro en el barrio universitario, le puse Simon de carinio. No tenia collar ni chapita. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 72 DAY), 9, 11, 9, 1),
(10, 'Se perdio mi gato llamado Tom en el centro. Es usa collar rojo. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 70 DAY), 10, 12, 10, 1),
(11, 'Encontre un perro en la zona norte, le puse Bruno de carinio. Es muy manso. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 68 DAY), 11, 13, 11, 1),
