(43, 'Se perdio mi perro llamado Nube en cerca de la terminal. Es tiene una mancha particular en el lomo. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 4 DAY), 43, 9, 43, 1),
(44, 'Se perdio mi gato llamado Bigotes en la costa. Es responde a su nombre. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 2 DAY), 44, 10, 44, 1),
(45, 'Se perdio mi perro llamado Tango en barrio Belgrano. Es es de contextura pequenia. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 1 DAY), 45, 11, 45, 1),
(46, 'Se perdio mi gato llamado Estrella en zona sur. Es tiene una pata lastimada. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 1 DAY), 46, 12, 46, 1),
(47, 'Encontre un perro en las quintas, le puse Rocco de carinio. No tiene microchip. Si es tuyo o conoces al duenio, escribime.', DATE_SUB(CURDATE(), INTERVAL 1 DAY), 47, 13, 47, 1),
(48, 'Se perdio mi gato llamado Kiwi en cerca de la plaza principal. Es muy carinioso. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 1 DAY), 48, 14, 48, 1),
(49, 'Se perdio mi perro llamado Fido en el barrio universitario. Es asustadizo con los ruidos fuertes. Cualquier dato que puedan aportar se agradece mucho.', DATE_SUB(CURDATE(), INTERVAL 1 DAY), 49, 15, 49, 1),
(50, 'Michi es un gato que esta en adopcion. Fue rescatado y ya esta vacunado y desparasitado. Buscamos una familia responsable en el centro.', DATE_SUB(CURDATE(), INTERVAL 1 DAY), 50, 16, 50, 1);
